import {language} from './i18n.js';
import bank from './v3/bank.json' with {type:'json'};
import knowledge from '../data/knowledge/current.json' with {type:'json'};
import {escapeHTML as e} from './explorer-views.js';
const L=(en,zh,ms)=>({en,'zh-CN':zh,ms})[language];
export function productionHome(resume=false){
 const occupations=knowledge.records.filter(r=>r.source==='onet');
 const nodes=[['SW',390,170],['DATA',178,265],['DES',470,335],['PM',260,440],['HLT',90,125],['FIN',430,490]];
 const graph=`<svg viewBox="0 0 570 570" role="img" aria-label="${L('Explore connected career directions. Illustrative layout; distances do not measure suitability.','探索相连的职业方向。示意布局，距离不表示适合度。','Terokai arah kerjaya berkaitan. Susun atur ilustrasi; jarak bukan kesesuaian.')}"><defs><pattern id="career-grid" width="38" height="38" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="#c4cfc7"/></pattern></defs><rect width="570" height="570" fill="url(#career-grid)"/><g class="home-orbits" fill="none" stroke="#bccbc1"><circle cx="285" cy="285" r="112"/><circle cx="285" cy="285" r="204"/><path d="M90 125L178 265 260 440 430 490 470 335 390 170 90 125M178 265L390 170M260 440L470 335"/></g><g>${nodes.map(([id,x,y],i)=>`<g class="home-graph-node" style="--node:${i}" transform="translate(${x} ${y})"><circle r="${i===0?13:8}" fill="${i===0?'#326b54':'#e4ebe3'}" stroke="#326b54"/><text x="${i===2?-12:18}" y="${i===2?32:-16}" text-anchor="${i===2?'end':'start'}" fill="#214939">${e(bank.tracks.find(t=>t.id===id).label[language].split(' & ')[0].split('与')[0])}</text></g>`).join('')}</g><g transform="translate(285 285)"><circle r="35" fill="#183d32"/><path d="M-12 0H12M0-12V12" stroke="#d5e5bd" stroke-width="2"/><circle class="home-pulse" r="45" fill="none" stroke="#326b54"/></g></svg>`;
 return `<main class="production-home"><section class="shell production-hero"><div class="production-hero-copy"><span class="production-kicker"><i></i>${L('A CLEARER VIEW OF WHAT COMES NEXT','看清变化，看见下一步','PANDANGAN LEBIH JELAS UNTUK LANGKAH SETERUSNYA')}</span><h1>${L('Work is changing.<br>Your next move<br><em>starts with clarity.</em>','工作正在改变。<br>下一步，<br><em>从看清方向开始。</em>','Kerja sedang berubah.<br>Langkah seterusnya<br><em>bermula dengan jelas.</em>')}</h1><p>${L('Understand how AI reshapes real work. Connect your experience to career directions, then build a plan you can put to the test.','理解 AI 如何重塑真实工作。将你的经历与职业方向连接起来，再用实践检验下一步计划。','Fahami cara AI mengubah kerja sebenar. Hubungkan pengalaman anda dengan arah kerjaya, kemudian bina pelan untuk diuji.')}</p><div class="hero-buttons"><button class="button primary" data-action="start">${resume?L('Continue my exploration','继续我的探索','Sambung penerokaan saya'):L('Find my next direction','寻找我的下一步','Cari arah seterusnya')} <span>↗</span></button><a class="production-link" href="#how-it-works">${L('See how it works','了解工作原理','Lihat cara ia berfungsi')} ↓</a></div><span class="production-privacy">${L('No account needed · Core analysis runs on your device','无需账号 · 核心分析在本机完成','Tiada akaun diperlukan · Analisis teras pada peranti anda')}</span></div><div class="production-hero-graph"><div class="production-graph-top"><span>${L('YOUR FIELD OF POSSIBILITIES','你的可能性空间','RUANG KEMUNGKINAN ANDA')}</span><span>↗</span></div>${graph}<div class="production-graph-bottom"><span>${L('Career directions, connected.','职业方向，相互连接。','Arah kerjaya, saling berhubung.')}</span><small>${L('Illustrative layout · not a fit score','示意布局 · 非适合度评分','Susun atur ilustrasi · bukan skor kesesuaian')}</small></div></div></section><section class="production-proof shell"><span>${L('Built on occupational evidence','以职业证据为基础','Berasaskan bukti pekerjaan')}</span><strong>O*NET</strong><strong>ESCO</strong><span>${occupations.length} ${L('reference occupations','项参考职业','pekerjaan rujukan')}</span><span>${L('US context · Malaysia context clearly scoped','美国资料 · 明确标注马来西亚适用范围','Konteks AS · skop Malaysia dinyatakan')}</span></section><section id="how-it-works" class="shell production-approach"><div><span class="production-kicker">01 — ${L('UNDERSTAND THE WORK','先理解工作','FAHAMI TUGAS')}</span><h2>${L('A job title tells<br>only half the story.','职业名称，<br>只讲了一半故事。','Nama jawatan hanya<br>sebahagian cerita.')}</h2></div><div><p class="production-big-copy">${L('Look closer at the tasks. Some can be assisted by AI. Others depend on judgment, context and people. That is where your exploration begins.','走近具体任务：有些可以借助 AI，有些更依赖判断、情境与协作。你的探索，从这里开始。','Lihat tugas dengan lebih dekat. Ada yang boleh dibantu AI. Yang lain bergantung pada pertimbangan, konteks dan manusia. Di situlah penerokaan bermula.')}</p><div class="production-task-example"><span>${L('Occupational facts','职业事实','Fakta pekerjaan')}</span><strong>${L('Tasks → Skills → Changing work','任务 → 技能 → 工作变化','Tugas → Kemahiran → Perubahan kerja')}</strong><p>${L('Source facts and product interpretations are labelled separately. AI impact is a planning hypothesis, never a probability of losing a job.','来源事实与产品推断分别标注。AI 影响是规划假设，不是失业概率。','Fakta sumber dan tafsiran produk dilabel berasingan. Kesan AI ialah hipotesis perancangan, bukan kebarangkalian kehilangan kerja.')}</p></div></div></section><section class="production-process"><div class="shell"><span class="production-kicker">02 — ${L('FROM UNDERSTANDING TO ACTION','从理解到行动','DARIPADA PEMAHAMAN KEPADA TINDAKAN')}</span><h2>${L('Less guessing.<br>More exploring.','少一点猜测，<br>多一些探索。','Kurangkan tekaan.<br>Lebihkan penerokaan.')}</h2><ol>${[[L('Start with your reality','从你的真实情况开始','Mulakan dengan keadaan sebenar'),L('Your context, concerns and twelve questions about the work you want to explore. Select real behaviors, not a personality label.','你的背景、顾虑，以及围绕目标方向的十二道题。选择具体行为，不贴人格标签。','Konteks, kebimbangan dan dua belas soalan tentang tugas yang ingin diterokai. Pilih tingkah laku sebenar.')],[L('See the connections','看见职业间的连接','Lihat hubungannya'),L('Explore the career galaxy, compare routes and examine the Skill DNA behind occupational requirements.','探索职业星图、比较路线，查看职业要求背后的 Skill DNA。','Terokai galaksi kerjaya, banding laluan dan teliti Skill DNA di sebalik keperluan pekerjaan.')],[L('Test a possible next chapter','试验下一种可能','Uji langkah yang mungkin'),L('Adjust your time and learning priorities in What If. Compare concrete milestones before committing to a direction.','在 What If 中调整时间和练习重点。先比较具体里程碑，再决定方向。','Laras masa dan keutamaan latihan dalam What If. Banding pencapaian konkrit sebelum membuat pilihan.')]].map(([h,p],i)=>`<li><span>0${i+1}</span><h3>${h}</h3><p>${p}</p></li>`).join('')}</ol></div></section><section class="shell production-final"><span class="production-kicker">${L('YOUR SKILLS. YOUR FUTURE. YOUR CHOICE.','你的能力。你的未来。你的选择。','KEMAHIRAN ANDA. MASA DEPAN ANDA. PILIHAN ANDA.')}</span><h2>${L('Give your next move<br>a stronger starting point.','让下一步，<br>有据可依。','Beri langkah seterusnya<br>asas yang lebih kukuh.')}</h2><button class="button primary" data-action="start">${L('Start exploring','开始探索','Mula meneroka')} ↗</button><p>${L('Exploratory guidance, not a validated aptitude test or a hiring prediction. Personal evidence remains self-reported until independently checked.','探索性指导，不是经过效度验证的能力测试或录用预测。个人证据在独立核验前均属自述。','Panduan penerokaan, bukan ujian bakat disahkan atau ramalan pengambilan kerja. Bukti peribadi kekal laporan kendiri sehingga disemak.')}</p></section></main>`;
}
